import React from 'react';

function createIcon(shapes) {
  function Icon({ size = 16, color = 'currentColor', strokeWidth = 1, className = '', ...props }) {
    return (
      <svg
        width={size}
        height={size}
        viewBox="0 0 24 24"
        fill="none"
        stroke={color}
        strokeWidth={strokeWidth}
        strokeLinecap="round"
        strokeLinejoin="round"
        className={className}
        aria-hidden={props['aria-label'] ? undefined : true}
        {...props}
      >
        {shapes}
      </svg>
    );
  }
  return Icon;
}

